handleEvent(event) {
  switch (event.type) {
    case "input":
    case "change":
      this.#touchedInputs.add(event.currentTarget);
      this.checkValidEmailForm({ showErrors: false });
      break;
    case "click":
      if (event.target.id == "manualConfiguration") {
        this.dispatchEvent(
          new CustomEvent("edit-configuration", {
            bubbles: true,
          })
        );
      }
      break;
    default:
      break;
  }
}
